#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>
#include <errno.h>
#include "crefl.h"

static int n_ok, n_bad;
static crefl_ctx_t *ctx;

static void chk(const char *what, long long crefl, long long cc)
{
	if (crefl == cc) {
		n_ok++;
		printf("match  %s\n", what);
	} else {
		n_bad++;
		printf("DIFFER %s: crefl=%lld cc=%lld\n", what, crefl, cc);
	}
}

static const crefl_type_t *ty(const char *name)
{
	const crefl_type_t *t = crefl_type(ctx, name);

	if (t == NULL) {
		printf("DIFFER type %s: %s\n", name, crefl_errmsg(ctx));
		exit(1);
	}
	return t;
}

static long long path_off(const char *tn, const char *m)
{
	crefl_path_t p;

	return crefl_path(ty(tn), m, &p) ? -1 : (long long)p.off;
}

static long long path_size(const char *tn, const char *m)
{
	crefl_path_t p;

	return crefl_path(ty(tn), m, &p) ? -1 : (long long)crefl_sizeof(p.t);
}

static crefl_val_t val(const char *tn, void *p, const char *m)
{
	return crefl_get(crefl_wrap(ty(tn), p), m);
}

/*
 * The checks are functions, the macros only add what needs the
 * compiler: sizeof, offsetof and member assignment. Large macro bodies
 * made compiling the generated programs the slowest part of the tests.
 */
static void chk_layout(const char *tn, size_t size, size_t align)
{
	char w[512];

	snprintf(w, sizeof(w), "sizeof(%s)", tn);
	chk(w, crefl_sizeof(ty(tn)), size);
	snprintf(w, sizeof(w), "alignof(%s)", tn);
	chk(w, crefl_alignof(ty(tn)), align);
}

static void chk_off(const char *tn, const char *m, size_t off, size_t size)
{
	char w[512];

	snprintf(w, sizeof(w), "offsetof(%s, %s)", tn, m);
	chk(w, path_off(tn, m), off);
	snprintf(w, sizeof(w), "sizeof(%s.%s)", tn, m);
	chk(w, path_size(tn, m), size);
}

#define LAYOUT(tn, T) chk_layout(tn, sizeof(T), _Alignof(T))
#define OFF(tn, T, m) chk_off(tn, #m, offsetof(T, m), sizeof(((T *)0)->m))

/* instances: a is set by the compiler, b by crefl, both zeroed */
static unsigned char *chk_a, *chk_b;
static size_t chk_n;

static void chk_inst(size_t n)
{
	if (n > chk_n) {
		free(chk_a);
		free(chk_b);
		chk_a = malloc(n);
		chk_b = malloc(n);
		if (chk_a == NULL || chk_b == NULL) {
			printf("DIFFER out of memory\n");
			exit(1);
		}
		chk_n = n;
	}
	memset(chk_a, 0, n);
	memset(chk_b, 0, n);
}

#define INST(T)                     \
	chk_inst(sizeof(T));        \
	T *a_ = (T *)(void *)chk_a; \
	T *b_ = (T *)(void *)chk_b; \
	(void)b_

static void chk_acc_i(const char *tn, const char *m, const char *xs, size_t n,
		      int64_t x)
{
	char w[512];
	int64_t g = 0;
	int r = crefl_set_i64(val(tn, chk_b, m), x);

	snprintf(w, sizeof(w), "set %s.%s = %s", tn, m, xs);
	chk(w, r ? r : memcmp(chk_a, chk_b, n), 0);
	r = crefl_get_i64(val(tn, chk_a, m), &g);
	snprintf(w, sizeof(w), "get %s.%s == %s", tn, m, xs);
	chk(w, r ? r : g == x, 1);
}

static void chk_acc_u(const char *tn, const char *m, const char *xs, size_t n,
		      uint64_t x)
{
	char w[512];
	uint64_t g = 0;
	int r = crefl_set_u64(val(tn, chk_b, m), x);

	snprintf(w, sizeof(w), "set %s.%s = %s", tn, m, xs);
	chk(w, r ? r : memcmp(chk_a, chk_b, n), 0);
	r = crefl_get_u64(val(tn, chk_a, m), &g);
	snprintf(w, sizeof(w), "get %s.%s == %s", tn, m, xs);
	chk(w, r ? r : g == x, 1);
}

/* compiler and crefl set the same value into zeroed instances, then each reads the other's */
#define ACC_I(tn, T, m, x)                             \
	do {                                           \
		INST(T);                               \
		a_->m = (x);                           \
		chk_acc_i(tn, #m, #x, sizeof(T), (x)); \
	} while (0)

#define ACC_U(tn, T, m, x)                             \
	do {                                           \
		INST(T);                               \
		a_->m = (x);                           \
		chk_acc_u(tn, #m, #x, sizeof(T), (x)); \
	} while (0)

#define ACC_P(tn, T, m)                                      \
	do {                                                 \
		INST(T);                                     \
		a_->m = (void *)0x1230;                      \
		chk_acc_u(tn, #m, "ptr", sizeof(T), 0x1230); \
	} while (0)

/* floats: compare values, x87 long double has undefined padding bytes */
#define ACC_F(tn, T, m, x)                                                 \
	do {                                                               \
		INST(T);                                                   \
		double g_ = 0;                                             \
		a_->m = (x);                                               \
		int r_ = crefl_set_f64(val(tn, b_, #m), (x));              \
		chk("set " tn "." #m " = " #x, r_ ? r_ : b_->m == (x), 1); \
		r_ = crefl_get_f64(val(tn, a_, #m), &g_);                  \
		chk("get " tn "." #m " == " #x, r_ ? r_ : g_ == (x), 1);   \
	} while (0)

/* out of range sets must fail with -ERANGE */
static void chk_range(const char *tn, const char *m, const char *xs, size_t n,
		      int sgn, uint64_t x)
{
	char w[512];
	int r;

	chk_inst(n);
	r = sgn ? crefl_set_i64(val(tn, chk_b, m), (int64_t)x) :
		  crefl_set_u64(val(tn, chk_b, m), x);
	snprintf(w, sizeof(w), "range %s.%s = %s", tn, m, xs);
	chk(w, r, -ERANGE);
}

#define RANGE_I(tn, T, m, x) chk_range(tn, #m, #x, sizeof(T), 1, (int64_t)(x))
#define RANGE_U(tn, T, m, x) chk_range(tn, #m, #x, sizeof(T), 0, (x))

#define ENUMV(tn, e)                                                      \
	do {                                                              \
		const crefl_type_t *t_ = ty(tn);                          \
		long long v_ = -999999;                                   \
		for (size_t i_ = 0; i_ < crefl_len(t_); i_++) {           \
			if (strcmp(crefl_enumval(t_, i_)->name, #e) == 0) \
				v_ = crefl_enumval(t_, i_)->val;          \
		}                                                         \
		chk("enum " #e, v_, (long long)(e));                      \
	} while (0)

static char *print_all(crefl_ctx_t *c)
{
	char *out = NULL;
	size_t len = 0;
	FILE *f = open_memstream(&out, &len);

	for (size_t i = 0; i < crefl_ntypes(c); i++)
		crefl_print(crefl_type_at(c, i), f);
	fclose(f);
	return out;
}

/* layout signature: resolved kinds, sizes, member offsets and bits */
static void sig_r(const crefl_type_t *t, FILE *f, int depth)
{
	t = crefl_resolve(t);
	fprintf(f, "(k%d p%d s%zu a%zu", crefl_kind(t),
		crefl_kind(t) == CREFL_PRIM ? (int)crefl_prim(t) : -1,
		crefl_sizeof(t), crefl_alignof(t));

	if (depth < 8) {
		switch (crefl_kind(t)) {
		case CREFL_ARRAY:
			fprintf(f, " n%zu", crefl_len(t));
			sig_r(crefl_elem(t), f, depth + 1);
			break;
		case CREFL_STRUCT:
		case CREFL_UNION:
			for (size_t i = 0; i < crefl_len(t); i++) {
				const crefl_member_t *m = crefl_member(t, i);

				fprintf(f, " %s@%zu.%u:%u",
					m->name ? m->name : "-", m->off,
					m->bit_off, m->bit_width);
				sig_r(m->type, f, depth + 1);
			}
			break;
		case CREFL_ENUM:
			for (size_t i = 0; i < crefl_len(t); i++)
				fprintf(f, " %s=%lld",
					crefl_enumval(t, i)->name,
					(long long)crefl_enumval(t, i)->val);
			break;
		default:
			break;
		}
	}
	fprintf(f, ")");
}

static char *print_one(const crefl_type_t *t)
{
	char *out = NULL;
	size_t len = 0;
	FILE *f = open_memstream(&out, &len);

	sig_r(t, f, 0);
	fprintf(f, "\n");
	fclose(f);
	return out;
}

/* print all types, parse the output again, the second print must be identical */
static void roundtrip(void)
{
	crefl_ctx_t *c2 = crefl_ctx_new();
	char *a = print_all(ctx), *b = NULL;
	int ret = crefl_parse(c2, a);

	if (ret)
		printf("DIFFER roundtrip parse: %s\n", crefl_errmsg(c2));
	else
		b = print_all(c2);
	chk("roundtrip print", ret ? ret : strcmp(a, b) != 0, 0);
	if (b && strcmp(a, b))
		printf("--- first\n%s--- second\n%s", a, b);
	free(a);
	free(b);
	crefl_ctx_free(c2);
}

static const crefl_type_t *same_named(const crefl_type_t *t)
{
	char name[300];
	const char *kw = "";

	switch (crefl_kind(t)) {
	case CREFL_STRUCT:
		kw = "struct ";
		break;
	case CREFL_UNION:
		kw = "union ";
		break;
	case CREFL_ENUM:
		kw = "enum ";
		break;
	default:
		break;
	}
	snprintf(name, sizeof(name), "%s%s", kw, crefl_name(t));
	return crefl_type(ctx, name);
}

/*
 * parse the header without preprocessor, all types must have the
 * same layout signature as from the preprocessed source. Headers that need macros or
 * local includes are expected to fail.
 */
static void raw_check(const char *raw, int needs_cpp)
{
	crefl_ctx_t *c3 = crefl_ctx_new();
	int ret = crefl_parse(c3, raw);

	if (ret && needs_cpp) {
		printf("skip   raw parse (needs preprocessor): %s\n",
		       crefl_errmsg(c3));
	} else if (ret) {
		printf("DIFFER raw parse: %s\n", crefl_errmsg(c3));
		n_bad++;
	} else {
		for (size_t i = 0; i < crefl_ntypes(c3); i++) {
			const crefl_type_t *t = crefl_type_at(c3, i),
					   *o = same_named(t);
			char *a = print_one(t), *b = o ? print_one(o) : NULL;
			char what[300];

			snprintf(what, sizeof(what), "raw %s", crefl_name(t));
			chk(what, b ? strcmp(a, b) != 0 : -1, 0);
			if (b && strcmp(a, b))
				printf("--- raw\n%s--- preprocessed\n%s", a, b);
			free(a);
			free(b);
		}
	}
	crefl_ctx_free(c3);
}

static int report(void)
{
	printf("%d match, %d differ\n", n_ok, n_bad);
	crefl_ctx_free(ctx);
	return n_bad != 0;
}
